ddimer_log.encoding:
ddimer_log = log_value('ddimer_feu', 1)

def log_value(key, floor=None):
    v = c.get(key, pd.Series(np.nan, index=c.index)).to_numpy(float)
    if floor is None:
        v = np.where(v > 0, v, np.nan)
    else:
        v = np.where(np.isfinite(v), np.maximum(v, floor), np.nan)
    return np.log(v)

